From 53f07b4d83c40e67b06ac39efd0b6d48d95264a8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 13:25:01 +0100
Subject: [PATCH] plugins/sessionquit: Fade windows to black while logging out

Logging out kept the desktop on screen for seconds, and setState() read
ksmserver's states shifted by one. Map them as documented and fade all
windows to black while quitting, except modal dialogs and new prompts.

BUG: 188476
---
 .../sessionquit/package/contents/code/main.js | 43 +++++++++++++++++++
 src/sm.cpp                                    |  4 +-
 2 files changed, 45 insertions(+), 2 deletions(-)

diff --git a/src/plugins/sessionquit/package/contents/code/main.js b/src/plugins/sessionquit/package/contents/code/main.js
index 6b73fd90b4..e6a6bb5324 100644
--- a/src/plugins/sessionquit/package/contents/code/main.js
+++ b/src/plugins/sessionquit/package/contents/code/main.js
@@ -25,8 +25,51 @@ var quitEffect = {
             to: 0.0
         });
     },
+    fadeOut: function (window) {
+        if (window.modal) {
+            return;
+        }
+        if (window.quitFadeAnimation) {
+            if (redirect(window.quitFadeAnimation, Effect.Forward)) {
+                return;
+            }
+            cancel(window.quitFadeAnimation);
+        }
+        window.quitFadeAnimation = set({
+            window: window,
+            curve: QEasingCurve.InOutSine,
+            duration: animationTime(600),
+            keepAlive: false,
+            animations: [
+                {
+                    type: Effect.Opacity,
+                    to: 0.0
+                }
+            ]
+        });
+    },
+    fadeIn: function (window) {
+        if (!window.quitFadeAnimation) {
+            return;
+        }
+        if (!redirect(window.quitFadeAnimation, Effect.Backward)) {
+            cancel(window.quitFadeAnimation);
+        }
+        delete window.quitFadeAnimation;
+    },
+    sessionStateChanged: function () {
+        // Modal dialogs and windows that show up while quitting, such as "Save
+        // changes?" prompts or the notification about applications that did not
+        // close, stay visible.
+        var fade = effects.sessionState == Globals.Quitting ? quitEffect.fadeOut : quitEffect.fadeIn;
+        var windows = effects.stackingOrder;
+        for (var i = 0; i < windows.length; ++i) {
+            fade(windows[i]);
+        }
+    },
     init: function () {
         effects.windowClosed.connect(quitEffect.closed);
+        effects.sessionStateChanged.connect(quitEffect.sessionStateChanged);
     }
 };
 quitEffect.init();
diff --git a/src/sm.cpp b/src/sm.cpp
index 7a4591880a..abdd316cb2 100644
--- a/src/sm.cpp
+++ b/src/sm.cpp
@@ -317,10 +317,10 @@ SessionState SessionManager::state() const
 void SessionManager::setState(uint state)
 {
     switch (state) {
-    case 0:
+    case 1:
         setState(SessionState::Saving);
         break;
-    case 1:
+    case 2:
         setState(SessionState::Quitting);
         break;
     default:
